import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第60章 窗玻璃","description":"","frontmatter":{},"headers":[],"relativePath":"第60章_窗玻璃.md","filePath":"第60章_窗玻璃.md"}'),o={name:"第60章_窗玻璃.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第60章-窗玻璃" tabindex="-1">第60章 窗玻璃 <a class="header-anchor" href="#第60章-窗玻璃" aria-label="Permalink to &quot;第60章 窗玻璃&quot;">​</a></h1><p>九月四号，我坐上去澄江的车。</p><p>那天早上我妈送我。</p><p>她送我到进站口，把包从我手里拿过去，又塞回来。</p><p>她说，你自己拿。</p><p>我说，我自己拿。</p><p>她在闸机外面站着，隔着那个铁栏杆看我。</p><p>我刷身份证的时候，听见她在背后跟一个人说话。</p><p>她说，他小时候就这样，一站起来就走。</p><p>我不知道她在跟谁说。我回头看了一眼，她正在跟闸机边上那个穿制服的人说。</p><p>那个穿制服的人笑了一下。</p><p>我妈不是那种会在人前多话的人。</p><p>我这辈子只见过她三次这样，每一次都是有人要走。</p><p>十八岁那年冬天，我去过这个站一次。</p><p>那次我买到了票。</p><p>那次我在检票口前面站着，站了很久，最后把那张票留在口袋里，转身走了。</p><p>这次我没有在检票口站着。</p><p>这次我进去了。</p><p>我上车以后找了半天才找到自己的位子。</p><p>车厢是满的，过道里全是箱子。我把我的箱子塞到座位底下的时候，蹲了很久，膝盖响了两声。</p><p>对面是一个大爷，带着一个很旧的旅行袋。</p><p>他把袋子放在自己脚边，两只手压在袋子上。</p><p>他一路都在看窗外，看得很认真。</p><p>车开了以后，我从包里拿出一瓶水，没喝，放在桌上。</p><p>三点四十，车开始过山。</p><p>一个洞，一个洞。</p><p>进洞的那一下，耳朵会嗡一声。</p><p>我给她发了一条。</p><p>我说，我上车了。</p><p>发出去以后，屏幕上那两个灰点还在。</p><p>我知道她看不见。</p><p>她那边的时间我不用纸也算得出来。</p><p>我这边三点四十，她那边是前一天晚上八点四十。</p><p>她前一天晚上八点四十在干什么，我不知道。</p><p>我只知道现在她那边是早上七点四十。</p><p>她要么在上课，要么在食堂，要么刚醒。</p><p>我靠着窗户，看外面。</p><p>外面的东西跑得很快，看不清，只有一种灰绿色一直在往后走。</p><p>车又进洞了。</p><p>一进去，屏幕上那两个字变了。</p><p>无服务。</p><p>我把手机拿在手里，看着那三个字。</p><p>洞很长。</p><p>我数了一下，那个洞我数了大概一分钟。</p><p>出洞的时候，屏幕上的字又回来了。</p><p>那条消息还是灰的。</p><p>大爷在对面打开了一盒泡面。</p><p>他拿保温杯去接水，接回来放在桌上，用一本书压着盖子。</p><p>他压好了坐下来，看了我一眼。</p><p>他说，上学？</p><p>我说，嗯。</p><p>他说，哪里。</p><p>我说，澄江。</p><p>他说，远啊。</p><p>我说，嗯。</p><p>他说，家里大人没送？</p><p>我抬了一下头。</p><p>我说，送了。</p><p>他说，送到哪儿。</p><p>我说，送到那个口。</p><p>大爷&quot;哦&quot;了一声。</p><p>他说，那就好。</p><p>他说，我送我孙子那年，我送到检票口，人家不让我进。</p><p>他说，我就在外头站着。</p><p>他说，站到我以为车开了。</p><p>他说，后来我回家，我儿子说那趟车晚点四十分钟。</p><p>他说，我白站了四十分钟。</p><p>我听着这一句，没有接话。</p><p>我那时候在想另一件事。</p><p>我在想我妈。</p><p>我妈在闸机外面站了多久。</p><p>我不知道。</p><p>我上车的时候没有回头看第二次。</p><p>我第一次回头，是她跟我说话之前。</p><p>第二次我没回。</p><p>我这一辈子最擅长的事，就是少回头那一次。</p><p>天快黑的时候，车停在一个大站。</p><p>大爷的泡面早就吃完了，盒子还在桌上。</p><p>我站起来活动，走到车厢连接的地方站着。</p><p>那里吵，风从底下往上灌。</p><p>外面在下雨。</p><p>我站在那儿，忽然发现一件事。</p><p>玻璃上有我自己的脸。</p><p>因为这边黑了，外面黑了，玻璃就变成一面镜子。</p><p>我看见我额头、一只眼睛、半边鼻子。</p><p>我看见我后面座位那一排，暗下去，看不清。</p><p>那一瞬间我想到的是三月里那张照片。</p><p>她发我的那张，机场，红色飞机尾巴，一块很亮的反光。</p><p>反光里有一个人，一只手举着手机，另一只手抓着背包带。</p><p>那块玻璃她大概一辈子没注意过。</p><p>她拍的是飞机。</p><p>她把自己留在了里面。</p><p>而现在我在另一块玻璃上，看见了我自己。</p><p>中间隔了一个半球。</p><p>我站在那儿，看着玻璃上我这张脸，忽然想到一件事，一件很具体的事。</p><p>我给她拍一张照片，是这一年以后的事。</p><p>我们两个这一辈子，没有一张照片里是两个人的。</p><p>不是没有合照。</p><p>是我们两个人一起被拍下来的那一种，一张也没有。</p><p>所以我们两个各自被留在了两块不同的玻璃上。</p><p>晚上八点，我到了。</p><p>出站的时候人特别多，我被人推着走。</p><p>有一个穿制服的在喊，往前走不要停。</p><p>我拖着箱子往前走。</p><p>我上了公交车，最后一排，把箱子放在腿边上。</p><p>车上的灯很白，照得人不好看。</p><p>宿舍是一间屋子里六张床。</p><p>我进门的时候，里面已经住了两个。</p><p>一个在铺被子，一个戴着耳机在剪指甲。</p><p>剪指甲那个人抬头看我，说，你哪个床。</p><p>我说，靠窗那个。</p><p>他说，我也是靠窗，里面那个。</p><p>他把指甲往前一推，让我进去。</p><p>我把箱子放在床底下。</p><p>我把那面墙用纸垫了一层。</p><p>我把她那个仓库的清单从书包里拿出来，压在枕头底下。</p><p>躺下来的时候，十一点半。</p><p>这边十一点半，她那边是凌晨三点半。</p><p>我知道这个数，因为这个数我不查也知道。</p><p>我把手机扣在枕头边上。</p><p>我快睡的时候，手机亮了一下。</p><p>我拿起来。</p><p>她那边凌晨三点四十一，不知道她为什么醒着。</p><p>她说，到了？</p><p>我说，到了。</p><p>她说，几点睡的。</p><p>我说，现在。</p><p>她说，我这里三点四十。</p><p>她说，你不要跟我算这个，我现在不想算。</p><p>我说，那你睡。</p><p>她说，你先睡。</p><p>我说，我不能先，我这边要是先睡了，你那边就天亮了你又要上课。</p><p>她说，你这个人。</p><p>她说，晚安。</p><p>我看着她那两个字。</p><p>我说，晚安。</p><p>我关了屏幕。</p><p>那天夜里我宿舍六个人，三个醒着。</p><p>一个在跟家里打电话，声音压得很低。</p><p>一个在洗袜子。</p><p>我在数一个我不该记得这么熟的时差。</p><p>从这天起，我们两个隔了一个半球。</p><p>我这边天黑，她那边天亮。</p><p>我这边上课，她那边睡觉。</p><p>我这一辈子最远的距离，从此不是三百公里。</p><p>是这个屋子到那个屋子。</p>',146)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
